"""Build the independent PPT visual-QA holdout fixture.

The clean source images are generated by the real isolated PPT Skill Runner.
Broken cases are deterministic image mutations applied only after that real
render, and are recorded in the immutable Gold Set with their source slide and
mutation description.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import random
import sys
import urllib.request
from datetime import datetime, timezone
from pathlib import Path
from typing import Callable, Iterable

from PIL import Image, ImageDraw, ImageFont


ROOT = Path(__file__).resolve().parent
DEFAULT_OUT = ROOT / "visual-qa-holdout"
RUNNER_URL = os.environ.get("PPT_VISUAL_QA_HOLDOUT_RUNNER_URL", "http://127.0.0.1:38090").rstrip("/")
STYLE_PRESET = "forest-research"

OBJECTIVE_CODES = [
    "TEXT_OVERFLOW", "TEXT_TOO_SMALL", "ELEMENT_OVERLAP", "ELEMENT_CLIPPED",
    "LOW_CONTRAST", "TABLE_UNREADABLE", "CHART_UNREADABLE", "FLOW_UNREADABLE",
    "BROKEN_RENDERING",
]
SUBJECTIVE_CODES = [
    "UNBALANCED_LAYOUT", "EXCESSIVE_EMPTY_SPACE", "VISUAL_HIERARCHY_WEAK", "DENSE_CONTENT",
]


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def font(size: int, bold: bool = False) -> ImageFont.FreeTypeFont | ImageFont.ImageFont:
    candidates = [
        Path("C:/Windows/Fonts/segoeuib.ttf" if bold else "C:/Windows/Fonts/segoeui.ttf"),
        Path("C:/Windows/Fonts/arialbd.ttf" if bold else "C:/Windows/Fonts/arial.ttf"),
        Path("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"),
    ]
    for candidate in candidates:
        if candidate.exists():
            return ImageFont.truetype(str(candidate), size)
    return ImageFont.load_default()


