def call_runner(out_dir: Path) -> dict:
    payload = json.dumps({"outline": outline(), "stylePreset": STYLE_PRESET}).encode("utf-8")
    request = urllib.request.Request(
        f"{RUNNER_URL}/internal/ppt-skill/v1/generations",
        data=payload,
        headers={"Content-Type": "application/json; charset=utf-8"},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=900) as response:
        result = json.loads(response.read().decode("utf-8"))
    (out_dir / "runner-generation.json").write_text(json.dumps(result, indent=2) + "\n", encoding="utf-8")
    for slide_number in range(1, len(outline()["slides"]) + 1):
        url = f"{RUNNER_URL}/internal/ppt-skill/v1/jobs/{result['jobId']}/previews/{slide_number}"
        with urllib.request.urlopen(url, timeout=120) as response:
            (out_dir / f"source-slide-{slide_number:02d}.png").write_bytes(response.read())
    return result


def overlay(image: Image.Image) -> tuple[Image.Image, ImageDraw.ImageDraw]:
    layer = Image.new("RGBA", image.size, (0, 0, 0, 0))
    return layer, ImageDraw.Draw(layer)


def apply_layer(image: Image.Image, layer: Image.Image) -> Image.Image:
    return Image.alpha_composite(image.convert("RGBA"), layer).convert("RGB")


def mutate_text_overflow(image: Image.Image) -> Image.Image:
    w, h = image.size
    layer, draw = overlay(image)
    draw.rounded_rectangle((int(w * .56), int(h * .76), w + 90, h + 45), radius=12, fill=(21, 48, 70, 245))
    draw.text((int(w * .58), int(h * .79)), "A long footer annotation is clipped at the bottom edge", font=font(26), fill=(248, 180, 62, 255))
    return apply_layer(image, layer)


def mutate_text_too_small(image: Image.Image) -> Image.Image:
    w, h = image.size
    layer, draw = overlay(image)
    draw.rectangle((int(w * .10), int(h * .84), int(w * .90), int(h * .96)), fill=(247, 245, 235, 240))
    tiny = font(8)
    for index in range(8):
        draw.text((int(w * .12), int(h * (.845 + index * .013))), "footnote label / source reference / observation", font=tiny, fill=(92, 103, 110, 255))
    return apply_layer(image, layer)


def mutate_overlap(image: Image.Image) -> Image.Image:
    w, h = image.size
    layer, draw = overlay(image)
    draw.rounded_rectangle((int(w * .27), int(h * .30), int(w * .76), int(h * .72)), radius=16, fill=(13, 84, 87, 235))
    draw.rounded_rectangle((int(w * .48), int(h * .51), int(w * .92), int(h * .84)), radius=16, fill=(217, 82, 57, 245))
    draw.text((int(w * .33), int(h * .47)), "blocked reading path", font=font(28, True), fill=(255, 255, 255, 255))
    return apply_layer(image, layer)


def mutate_clipped(image: Image.Image) -> Image.Image:
    w, h = image.size
    layer, draw = overlay(image)
    draw.rounded_rectangle((w - 160, h - 170, w + 130, h + 95), radius=18, fill=(74, 43, 94, 245), outline=(248, 180, 62, 255), width=8)
    draw.text((w - 140, h - 120), "edge object", font=font(30, True), fill=(255, 255, 255, 255))
    return apply_layer(image, layer)


def mutate_low_contrast(image: Image.Image) -> Image.Image:
    w, h = image.size
    layer, draw = overlay(image)
    draw.rectangle((int(w * .08), int(h * .27), int(w * .92), int(h * .72)), fill=(235, 235, 224, 190))
    draw.text((int(w * .16), int(h * .45)), "important annotation", font=font(32, True), fill=(211, 213, 202, 255))
    draw.text((int(w * .16), int(h * .54)), "low contrast against the panel", font=font(25), fill=(214, 216, 207, 255))
    return apply_layer(image, layer)


def mutate_table(image: Image.Image) -> Image.Image:
    w, h = image.size
    layer, draw = overlay(image)
    top = int(h * .38)
    bottom = int(h * .84)
    draw.rectangle((int(w * .10), top, int(w * .90), bottom), fill=(229, 226, 211, 245), outline=(23, 49, 66, 255), width=5)
    for y in range(top + 42, bottom, 46):
        draw.rectangle((int(w * .10), y, int(w * .90), y + 19), fill=(19, 31, 42, 245))
    for x in [int(w * .36), int(w * .62)]:
        draw.line((x, top, x, bottom), fill=(19, 31, 42, 255), width=5)
    return apply_layer(image, layer)


def mutate_chart(image: Image.Image) -> Image.Image:
    w, h = image.size
    layer, draw = overlay(image)
    draw.rectangle((int(w * .13), int(h * .30), int(w * .87), int(h * .78)), fill=(241, 240, 232, 218))
    for offset in range(0, 18):
        y = int(h * (.34 + offset * .021))
        draw.line((int(w * .17), y, int(w * .84), y), fill=(190, 194, 188, 220), width=3)
    draw.text((int(w * .24), int(h * .48)), "axis labels / legend / values", font=font(9), fill=(196, 198, 191, 255))
    return apply_layer(image, layer)


def mutate_flow(image: Image.Image) -> Image.Image:
    w, h = image.size
    layer, draw = overlay(image)
    for i in range(7):
        x = int(w * (.18 + i * .10))
        draw.line((x, int(h * .28), x + 180, int(h * .80)), fill=(210, 65, 50, 235), width=18)
    for x in [int(w * .20), int(w * .45), int(w * .70)]:
        draw.ellipse((x, int(h * .48), x + 120, int(h * .60)), fill=(18, 67, 83, 245))
    draw.text((int(w * .18), int(h * .65)), "steps cannot be followed", font=font(28, True), fill=(255, 255, 255, 255))
    return apply_layer(image, layer)


def mutate_rendering(image: Image.Image) -> Image.Image:
    w, h = image.size
    layer, draw = overlay(image)
    rng = random.Random(16016)
    for index in range(24):
        y = int(h * .25 + index * h * .022)
        height = rng.randint(7, 19)
        color = (rng.randint(15, 245), rng.randint(15, 245), rng.randint(15, 245), 230)
        draw.rectangle((int(w * (.08 + rng.random() * .08)), y, int(w * (.86 + rng.random() * .12)), y + height), fill=color)
    draw.line((int(w * .12), int(h * .27), int(w * .90), int(h * .80)), fill=(0, 0, 0, 255), width=12)
    return apply_layer(image, layer)


def mutate_unbalanced(image: Image.Image) -> Image.Image:
    w, h = image.size
    layer, draw = overlay(image)
    draw.rectangle((int(w * .58), int(h * .17), int(w * .98), int(h * .92)), fill=(9, 31, 42, 250))
    draw.rounded_rectangle((int(w * .09), int(h * .76), int(w * .25), int(h * .85)), radius=8, fill=(218, 82, 57, 255))
    return apply_layer(image, layer)


def mutate_empty(image: Image.Image) -> Image.Image:
    w, h = image.size
    bg = image.getpixel((2, 2))
    layer, draw = overlay(image)
    draw.rectangle((int(w * .36), int(h * .30), w - 2, h - 2), fill=(*bg, 255))
    draw.rounded_rectangle((int(w * .10), int(h * .58), int(w * .31), int(h * .70)), radius=8, fill=(20, 68, 83, 255))
    draw.text((int(w * .12), int(h * .605)), "one small island", font=font(18, True), fill=(255, 255, 255, 255))
    return apply_layer(image, layer)


def mutate_hierarchy(image: Image.Image) -> Image.Image:
    w, h = image.size
    layer, draw = overlay(image)
    colors = [(48, 83, 91, 245), (48, 83, 91, 245), (48, 83, 91, 245), (48, 83, 91, 245)]
    for index, color in enumerate(colors):
        x = int(w * (.10 + index * .21))
        draw.rounded_rectangle((x, int(h * .38), x + int(w * .16), int(h * .68)), radius=10, fill=color)
        draw.text((x + 18, int(h * .50)), f"block {index + 1}", font=font(24), fill=(224, 224, 215, 255))
    draw.text((int(w * .13), int(h * .73)), "No focal point; equal weight everywhere", font=font(22), fill=(36, 50, 55, 255))
    return apply_layer(image, layer)


def mutate_dense(image: Image.Image) -> Image.Image:
    w, h = image.size
    layer, draw = overlay(image)
    tiny = font(10)
    for row in range(13):
        y = int(h * .27 + row * h * .043)
        for col in range(6):
            x = int(w * .08 + col * w * .145)
            draw.rectangle((x, y, x + int(w * .12), y + 24), fill=(29, 67 + (row % 3) * 18, 79, 230), outline=(227, 171, 69, 255), width=2)
            draw.text((x + 5, y + 6), "dense note", font=tiny, fill=(255, 255, 255, 255))
    return apply_layer(image, layer)


MUTATIONS: dict[str, Callable[[Image.Image], Image.Image]] = {
    "TEXT_OVERFLOW": mutate_text_overflow,
    "TEXT_TOO_SMALL": mutate_text_too_small,
    "ELEMENT_OVERLAP": mutate_overlap,
    "ELEMENT_CLIPPED": mutate_clipped,
    "LOW_CONTRAST": mutate_low_contrast,
    "TABLE_UNREADABLE": mutate_table,
    "CHART_UNREADABLE": mutate_chart,
    "FLOW_UNREADABLE": mutate_flow,
    "BROKEN_RENDERING": mutate_rendering,
    "UNBALANCED_LAYOUT": mutate_unbalanced,
    "EXCESSIVE_EMPTY_SPACE": mutate_empty,
    "VISUAL_HIERARCHY_WEAK": mutate_hierarchy,
    "DENSE_CONTENT": mutate_dense,
}


