def build_gold(out_dir: Path) -> list[dict]:
    cases: list[dict] = []
    clean_types = [
        (1, "cover"), (2, "agenda"), (3, "concept"), (4, "comparison"),
        (5, "timeline-process"), (6, "chart"), (7, "table"), (8, "diagram"),
        (9, "activity-assessment"), (10, "summary"), (11, "summary-stats"), (12, "assessment"),
    ]
    clean_file_by_slide = {slide_number: f"clean-{slide_number:02d}-{slide_type}.png" for slide_number, slide_type in clean_types}
    source_fixture = "ppt-skill-runner:deterministic-holdout-outline-v1"
    for slide_number, slide_type in clean_types:
        source_name = f"source-slide-{slide_number:02d}.png"
        file_name = f"clean-{slide_number:02d}-{slide_type}.png"
        source_path = out_dir / source_name
        clean_path = out_dir / file_name
        if source_path.exists():
            source_path.replace(clean_path)
        elif not clean_path.exists():
            raise FileNotFoundError(f"Missing Runner clean source: {source_path}")
        cases.append({
            "caseId": f"clean-{slide_number:02d}-{slide_type}",
            "fileName": file_name,
            "slideNumber": slide_number,
            "slideType": slide_type,
            "knownClean": True,
            "expectedCodes": [],
            "expectedMaxSeverity": "INFO",
            "notes": "Fresh real Runner-rendered clean holdout slide; not copied from Development Gold Set.",
            "sourceFixture": source_fixture,
            "mutationDescription": "none",
            "sourceSlideNumber": slide_number,
        })
    for index, (case_id, source_slide, slide_type, expected_codes, severity, mutation_description) in enumerate(BROKEN_CASES, start=1):
        source_path = out_dir / clean_file_by_slide[source_slide]
        output_name = f"{case_id}.png"
        source_image = Image.open(source_path).convert("RGB")
        mutated = MUTATIONS[expected_codes[0]](source_image)
        # Apply a second mutation only where the Gold label contains a real
        # second defect; this keeps combined cases materially multi-defect.
        if len(expected_codes) > 1:
            mutated = MUTATIONS[expected_codes[1]](mutated)
        mutated.save(out_dir / output_name, format="PNG", optimize=True)
        cases.append({
            "caseId": case_id,
            "fileName": output_name,
            "slideNumber": 1,
            "slideType": slide_type,
            "knownClean": False,
            "expectedCodes": expected_codes,
            "expectedMaxSeverity": severity,
            "notes": "Fresh Runner source with a holdout-only visible mutation; expected codes are frozen before Kimi calls.",
            "sourceFixture": source_fixture,
            "mutationDescription": mutation_description,
            "sourceSlideNumber": source_slide,
        })
    return cases


def make_integrity_report(out_dir: Path, cases: list[dict], runner_result: dict) -> dict:
    all_hashes: dict[str, str] = {}
    observations = []
    clean_sources = {case["caseId"]: out_dir / case["fileName"] for case in cases if case["knownClean"]}
    clean_by_slide = {case["sourceSlideNumber"]: out_dir / case["fileName"] for case in cases if case["knownClean"]}
    for case in cases:
        path = out_dir / case["fileName"]
        with Image.open(path) as image:
            image.load()
            width, height = image.size
            pixels = list(image.convert("RGB").getdata())
        digest = sha256(path)
        duplicate_of = all_hashes.get(digest)
        all_hashes[digest] = case["caseId"]
        source_path = clean_by_slide.get(case["sourceSlideNumber"])
        diff_ratio = 0.0
        if not case["knownClean"] and source_path:
            with Image.open(source_path) as source_image:
                source_pixels = list(source_image.convert("RGB").getdata())
            differing = sum(1 for left, right in zip(source_pixels, pixels) if left != right)
            diff_ratio = differing / max(1, len(pixels))
        observations.append({
            "caseId": case["caseId"],
            "fileName": case["fileName"],
            "width": width,
            "height": height,
            "byteSize": path.stat().st_size,
            "sha256": digest,
            "duplicateOf": duplicate_of,
            "nonEmpty": path.stat().st_size > 0 and len(pixels) > 0,
            "mutationVisible": case["knownClean"] or diff_ratio >= 0.002,
            "pixelDiffRatio": round(diff_ratio, 6),
            "sourceFixture": case["sourceFixture"],
        })
    missing_codes = sorted(set(OBJECTIVE_CODES + SUBJECTIVE_CODES) - {code for case in cases for code in case["expectedCodes"]})
    duplicate_cases = [item["caseId"] for item in observations if item["duplicateOf"]]
    invalid_sources = [item["caseId"] for item in observations if item["sourceFixture"] != "ppt-skill-runner:deterministic-holdout-outline-v1"]
    return {
        "version": 2,
        "generatedAt": now_iso(),
        "runner": {"baseUrl": RUNNER_URL, "jobId": runner_result.get("jobId"), "status": runner_result.get("status"), "qaLevel": runner_result.get("qa", {}).get("qaLevel")},
        "caseCount": len(cases),
        "cleanCount": sum(1 for case in cases if case["knownClean"]),
        "brokenCount": sum(1 for case in cases if not case["knownClean"]),
        "dimensions": sorted({f"{item['width']}x{item['height']}" for item in observations}),
        "duplicateCases": duplicate_cases,
        "missingCodes": missing_codes,
        "invalidSourceCases": invalid_sources,
        "allNonEmpty": all(item["nonEmpty"] for item in observations),
        "allMutationsVisible": all(item["mutationVisible"] for item in observations),
        "passed": len(cases) == 30 and not duplicate_cases and not missing_codes and not invalid_sources and all(item["nonEmpty"] for item in observations) and all(item["mutationVisible"] for item in observations),
        "cases": observations,
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--out", type=Path, default=DEFAULT_OUT)
    parser.add_argument("--skip-runner", action="store_true")
    args = parser.parse_args()
    out_dir = args.out.resolve()
    out_dir.mkdir(parents=True, exist_ok=True)
    if not args.skip_runner:
        for path in out_dir.glob("*.png"):
            path.unlink()
        runner_result = call_runner(out_dir)
    else:
        runner_result = json.loads((out_dir / "runner-generation.json").read_text(encoding="utf-8"))
    cases = build_gold(out_dir)
    (out_dir / "holdout-runner-outline.json").write_text(json.dumps(outline(), indent=2) + "\n", encoding="utf-8")
    gold = {"version": 2, "source": "PPT-016 independent holdout; labels frozen before Kimi calls", "cases": cases}
    (out_dir / "holdout-gold-set.json").write_text(json.dumps(gold, indent=2) + "\n", encoding="utf-8")
    integrity = make_integrity_report(out_dir, cases, runner_result)
    (out_dir / "holdout-integrity-report.json").write_text(json.dumps(integrity, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"out": str(out_dir), "caseCount": len(cases), "cleanCount": integrity["cleanCount"], "brokenCount": integrity["brokenCount"], "dimensions": integrity["dimensions"], "passed": integrity["passed"]}, indent=2))
    if not integrity["passed"]:
        raise SystemExit("holdout fixture integrity failed")


if __name__ == "__main__":
    main()
